from collections import deque
from typing import List, Optional

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def rightmostNode(self, root: Optional[TreeNode]) -> List[int]:
        """Return rightmost node value at each level using BFS."""
        if not root:
            return []

        nodes = []
        queue = deque([root])

        while queue:
            level_size = len(queue)
            for i in range(level_size):
                node = queue.popleft()
                # current node is the rightmost node
                if i == level_size - 1:
                    nodes.append(node.val)
                # add nodes as normal to the queue
                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)

        return nodes
